#include "distribution/Distribution.h"
#include "common/SqliteMigration.h"
#include <ncrypt.h>
#include <fstream>
#include <iostream>
#include <algorithm>
using namespace aegis::distribution;
namespace aegis::distribution {std::string TestPublisherPublicKey;}
namespace {
struct Object{NCRYPT_HANDLE h=0;~Object(){if(h)NCryptFreeObject(h);}} fixtureProvider,fixtureKey;
Json cases=Json::array();
void Test(const char* name,const std::function<void()>& run){run();cases.push_back(name);}
void Reject(const std::function<void()>& run){bool failed=false;try{run();}catch(const std::exception&){failed=true;}Require(failed,"Expected rejection");}
void Put(const fs::path& path,const std::string& value){fs::create_directories(path.parent_path());std::ofstream stream(path,std::ios::binary);stream<<value;Require(bool(stream),"Create inert fixture");}
void Sign(const fs::path& root,const std::string& kind,uint64_t sequence){
    auto manifest=MakeManifest(root,kind,sequence,"18.0.0-test","Release");const auto raw=manifest.dump()+"\n";auto digest=Unhex(Hash({reinterpret_cast<const uint8_t*>(raw.data()),raw.size()}));DWORD n=0;Require(NCryptSignHash(fixtureKey.h,nullptr,digest.data(),DWORD(digest.size()),nullptr,0,&n,0)==ERROR_SUCCESS,"Test signature length");std::vector<uint8_t> sig(n);Require(NCryptSignHash(fixtureKey.h,nullptr,digest.data(),DWORD(digest.size()),sig.data(),n,&n,0)==ERROR_SUCCESS,"Sign inert fixture");AtomicWrite(root/ManifestName,raw);AtomicWrite(root/SignatureName,Hex(sig)+"\n");
}
void Key(){Require(NCryptOpenStorageProvider(&fixtureProvider.h,MS_KEY_STORAGE_PROVIDER,0)==ERROR_SUCCESS&&NCryptCreatePersistedKey(fixtureProvider.h,&fixtureKey.h,NCRYPT_ECDSA_P256_ALGORITHM,nullptr,0,0)==ERROR_SUCCESS&&NCryptFinalizeKey(fixtureKey.h,0)==ERROR_SUCCESS,"Ephemeral test signing key");DWORD n=0;Require(NCryptExportKey(fixtureKey.h,0,BCRYPT_ECCPUBLIC_BLOB,nullptr,nullptr,0,&n,0)==ERROR_SUCCESS,"Test public key length");std::vector<uint8_t> bytes(n);Require(NCryptExportKey(fixtureKey.h,0,BCRYPT_ECCPUBLIC_BLOB,nullptr,bytes.data(),n,&n,0)==ERROR_SUCCESS,"Test public key");TestPublisherPublicKey=Hex(bytes);}
fs::path Package(const fs::path& root,uint64_t sequence){fs::create_directory(root);Put(root/L"runtime/Aegis.exe","inert fixture, never executed");Put(root/L"Aegis.exe","inert bootstrap fixture");Sign(root,"portable",sequence);return root;}
void Crash(const fs::path& root,const fs::path& update,const std::wstring& at){
    auto exe=ExecutablePath();auto command=L"\""+exe.wstring()+L"\" --crash \""+root.wstring()+L"\" \""+update.wstring()+L"\" "+at+L" "+Wide(TestPublisherPublicKey);STARTUPINFOW startup{};startup.cb=sizeof(startup);PROCESS_INFORMATION process{};Require(CreateProcessW(exe.c_str(),command.data(),nullptr,nullptr,FALSE,CREATE_NO_WINDOW,nullptr,nullptr,&startup,&process)!=FALSE,"Launch interrupted update fixture");CloseHandle(process.hThread);Require(WaitForSingleObject(process.hProcess,30000)==WAIT_OBJECT_0,"Update fixture deadline");DWORD code=0;GetExitCodeProcess(process.hProcess,&code);CloseHandle(process.hProcess);Require(code==77,"Update fixture did not reach interruption point");
}
}
int wmain(int argc,wchar_t** argv){try{
    if(argc==7&&std::wstring(argv[1])==L"--crash"){TestPublisherPublicKey=Utf8(argv[6]);ApplyUpdate(argv[2],argv[3],[&](const char* at){if(Wide(at)==argv[4])TerminateProcess(GetCurrentProcess(),77);});return 2;}
    // argc is six: executable, --crash, root, source, checkpoint, public key.
    if(argc==6&&std::wstring(argv[1])==L"--crash"){TestPublisherPublicKey=Utf8(argv[5]);ApplyUpdate(argv[2],argv[3],[&](const char* at){if(Wide(at)==argv[4])TerminateProcess(GetCurrentProcess(),77);});return 2;}
    Require(argc==2,"Fresh output directory required");const auto out=fs::absolute(argv[1]);Require(!fs::exists(out),"Test output must be fresh");fs::create_directories(out);Key();const auto good=Package(out/L"good",1);
    Test("ECDSA publisher signature verifies complete tree",[&]{auto tree=Verify(good,"portable");Require(tree.manifest.at("sequence")==1,"Sequence");});
    Test("verification locks block concurrent content writes",[&]{auto tree=Verify(good,"portable");File writer(CreateFileW((good/L"runtime/Aegis.exe").c_str(),GENERIC_WRITE,FILE_SHARE_READ,nullptr,OPEN_EXISTING,0,nullptr));Require(writer.h==INVALID_HANDLE_VALUE,"Verified member remained writable");});
    Test("modified binary rejected",[&]{const auto dir=Package(out/L"modified",1);Put(dir/L"runtime/Aegis.exe","tampered");Reject([&]{Verify(dir,"portable");});});
    Test("extra executable rejected",[&]{const auto dir=Package(out/L"extra",1);Put(dir/L"unexpected.exe","inert");Reject([&]{Verify(dir,"portable");});});
    Test("missing member rejected",[&]{const auto dir=Package(out/L"missing",1);Require(fs::remove(dir/L"runtime/Aegis.exe"),"Remove owned inert fixture");Reject([&]{Verify(dir,"portable");});});
    Test("modified signed manifest rejected",[&]{const auto dir=Package(out/L"metadata",1);auto metadata=ReadJson(dir/ManifestName);metadata["sequence"]=999;AtomicJson(dir/ManifestName,metadata);Reject([&]{Verify(dir,"portable");});});
    Test("wrong trust anchor rejected",[&]{Reject([&]{Verify(good,"portable",false,std::string(144,'0'));});});
    Test("package kind mismatch rejected",[&]{Reject([&]{Verify(good,"engines");});});
    Test("traversal, ADS and reserved Windows paths rejected",[]{for(const auto* path:{"../evil.dll","C:/evil","runtime/../evil","runtime/a:stream","CON","runtime/NUL.dll","runtime/end.","runtime/a\\b","runtime//a"})Reject([&]{RelativeName(path);});});
    Test("case-insensitive member collisions rejected by signed contract",[&]{const auto dir=Package(out/L"case",1);auto data=ReadJson(dir/ManifestName);data["files"]["RUNTIME/Aegis.exe"]=data["files"]["runtime/Aegis.exe"];const auto raw=data.dump();auto hash=Unhex(Hash({reinterpret_cast<const uint8_t*>(raw.data()),raw.size()}));DWORD n=64;std::vector<uint8_t> sig(n);Require(NCryptSignHash(fixtureKey.h,nullptr,hash.data(),DWORD(hash.size()),sig.data(),n,&n,0)==ERROR_SUCCESS,"Sign collision fixture");AtomicWrite(dir/ManifestName,raw);AtomicWrite(dir/SignatureName,Hex(sig));Reject([&]{Verify(dir,"portable");});});
    const auto upgrade=Package(out/L"upgrade",2);
    Test("signed update activates copied immutable version",[&]{const auto root=Package(out/L"activation",1);ApplyUpdate(root,upgrade);const auto status=DeploymentStatus(root);Require(status.at("active")!="base"&&status.at("highestSequence")==2&&status.at("rollbackAvailable")==true,"Update activation");});
    Test("explicit rollback preserves anti-replay sequence",[&]{const auto root=Package(out/L"rollback",1);ApplyUpdate(root,upgrade);Rollback(root);const auto status=DeploymentStatus(root);Require(status.at("active")=="base"&&status.at("highestSequence")==2,"Rollback state");Reject([&]{ApplyUpdate(root,upgrade);});});
    Test("untrusted update leaves current selection unchanged",[&]{const auto root=Package(out/L"reject-update",1);const auto bad=Package(out/L"bad-update",2);Put(bad/L"runtime/Aegis.exe","bad");Reject([&]{ApplyUpdate(root,bad);});Require(DeploymentStatus(root).at("active")=="base","Invalid update activated");});
    Test("concurrent update lock is exclusive",[&]{const auto root=Package(out/L"locked",1);File lock(CreateFileW((root/L"update.lock").c_str(),GENERIC_WRITE,0,nullptr,CREATE_NEW,0,nullptr));Require(lock.h!=INVALID_HANDLE_VALUE,"Create exclusive fixture lock");Reject([&]{ApplyUpdate(root,upgrade);});});
    for(const auto* phase:{"copied","prepared","activated"})Test(("process termination at "+std::string(phase)+" is recoverable").c_str(),[&]{const auto root=Package(out/Wide("crash-"+std::string(phase)),1);Crash(root,upgrade,Wide(phase));RecoverUpdate(root);const auto status=DeploymentStatus(root);Require((status.at("active")=="base")==bool(std::string(phase)!="activated"),"Interrupted update selected wrong version");});
    Test("preferences migration retains values and an original backup",[&]{const auto file=out/L"preferences/preferences.json";Put(file,"{\"locale\":\"pt-BR\",\"theme\":\"dark\"}");auto migrated=MigratePreferences(file);Require(migrated.at("schema")==1&&migrated.at("locale")=="pt-BR"&&ReadJson(file.parent_path()/L"preferences.schema0.backup.json").at("theme")=="dark","Preferences migration");});
    Test("future preferences are refused without overwrite",[&]{const auto file=out/L"future/preferences.json";Put(file,"{\"schema\":99,\"locale\":\"en-US\"}");const auto before=HashFile(file);Reject([&]{MigratePreferences(file);});Require(HashFile(file)==before,"Future preferences changed");});
    Test("SQLite migration preserves records and consistent backup",[&]{sqlite3* db=nullptr;const auto file=out/L"legacy.sqlite";const auto path=Utf8(file.wstring());Require(sqlite3_open(path.c_str(),&db)==SQLITE_OK,"Open legacy fixture");Require(sqlite3_exec(db,"CREATE TABLE retained(value INTEGER);INSERT INTO retained VALUES(42)",nullptr,nullptr,nullptr)==SQLITE_OK,"Prepare legacy record");aegis::storage::Migrate(db,file,1);Require(aegis::storage::Integer(db,"SELECT value FROM retained")==42&&aegis::storage::Integer(db,"PRAGMA user_version")==1,"Migration changed data");sqlite3_close(db);const auto backup=path+".schema0.backup.sqlite";Require(sqlite3_open_v2(backup.c_str(),&db,SQLITE_OPEN_READONLY,nullptr)==SQLITE_OK,"Read migration backup");Require(aegis::storage::Integer(db,"SELECT value FROM retained")==42&&aegis::storage::Integer(db,"PRAGMA user_version")==0,"Backup mismatch");sqlite3_close(db);});
    Test("future SQLite schema rejected without changing it",[&]{sqlite3* db=nullptr;const auto file=out/L"future.sqlite";Require(sqlite3_open(Utf8(file.wstring()).c_str(),&db)==SQLITE_OK&&sqlite3_exec(db,"PRAGMA user_version=99",nullptr,nullptr,nullptr)==SQLITE_OK,"Future database fixture");Reject([&]{aegis::storage::Migrate(db,file,1);});Require(aegis::storage::Integer(db,"PRAGMA user_version")==99,"Future schema overwritten");sqlite3_close(db);});
    const Json result{{"phase","18"},{"status","PASS"},{"tests",cases.size()},{"cases",cases}};std::ofstream(out/L"results.json")<<result.dump(2);std::cout<<result.dump()<<'\n';return 0;
}catch(const std::exception& e){std::cerr<<e.what()<<'\n';return 1;}}
